      {
        id: "javascript-c15-u5-l4-diagnostico-de-bloqueio-do-event-loop",
        title: "Diagnóstico e monitoramento de bloqueio do Event Loop",
        subtitle: "Fluidez assíncrona · Detectando operações síncronas que travam o servidor inteiro",
        theory: "Por ser single-threaded para código JavaScript, qualquer operação síncrona demorada (como JSON.parse de 50MB, regex exponencial ou loops pesados) bloqueia o Event Loop, congelando todas as requisições ativas. Ferramentas como perf_hooks.monitorEventLoopDelay() medem latências anômalas com precisão de nanossegundos.",
        questions: [
          q("O que acontece com outros clientes conectados à API quando uma rota executa uma operação síncrona que leva 2 segundos?", "Todas as outras conexões ficam congeladas aguardando esses 2 segundos antes de receber qualquer processamento", ["Os outros clientes são transferidos para outro servidor","O Node.js divide o processador em abas"], "O código JavaScript roda em thread única; operações síncronas longas sequestram o Event Loop."),
          q("Qual módulo nativo do Node.js fornece a função monitorEventLoopDelay para aferir travamentos?", "node:perf_hooks", ["node:timers","node:cluster"], "monitorEventLoopDelay mede a diferença entre o tempo agendado de um timer e sua execução real."),
          q("O que é uma \"ReDoS\" (Regular Expression Denial of Service)?", "Um ataque onde uma entrada maliciosa induz backtracking catastrófico em uma regex, travando a CPU em 100%", ["Um vírus que apaga expressões regulares","Um comando que desativa o CSS"], "Regexes mal projetadas com quantificadores aninhados podem levar horas para avaliar textos curtos."),
          q("Como liberar o Event Loop durante o processamento de uma lista massiva de 100.000 itens?", "Dividindo o processamento em lotes com setImmediate() ou transferindo a computação para um Worker Thread", ["Executando o for de trás para frente","Colocando todos os itens em uma string única"], "setImmediate cede a vez ao Event Loop permitindo que I/O e novas requisições sejam atendidas."),
          t("Qual método nativo agenda uma função para a próxima iteração do ciclo do Event Loop sem atrasos fixos?", ["setImmediate"], "setImmediate cede a CPU para outras tarefas do Event Loop."),
          g("Complete a criação do monitor de atraso do Event Loop no módulo node:perf_hooks:", ["monitorEventLoopDelay"], "monitorEventLoopDelay mede a latência do Event Loop com alta resolução.", "import { ____ } from \"node:perf_hooks\";\nconst h = monitorEventLoopDelay({ resolution: 20 });"),
          o("Ordene a investigação de lentidão sistêmica em servidor Node.js:", ["Instrumentar a aplicação ativando o monitorEventLoopDelay de perf_hooks","Coletar métricas de percentil p99 de atraso do ciclo durante o pico de tráfego","Identificar rotas que correlacionam picos de atraso com CPU em 100%","Substituir funções síncronas bloqueantes por alternativas assíncronas ou workers"], "Instrumentação com perf_hooks, análise de p99, correlação de rotas e migração para workers."),
          p("Associe a fonte de bloqueio à sua estratégia de resolução:", [["Backtracking de Regex (ReDoS)","Substituir por validação sem quantificadores aninhados ou parsers"],["JSON.parse massivo","Utilizar streams de parsing incremental de JSON"],["Cálculo matemático pesado","Descarregar o cálculo para Worker Threads paralelas"],["Loop síncrono gigantesco","Fragmentar a iteração em lotes intercalados com setImmediate"]], "Manter o Event Loop desimpedido é o requisito fundamental para o alto throughput do Node.js.")
        ]
      },
      {
        id: "javascript-c15-u5-l5-reproducao-minima-e-hipoteses-testaveis-de-bugs",
        title: "Reprodução mínima e metodologia de hipóteses para bugs",
        subtitle: "Método científico na prática · Isolando problemas complexos em scripts mínimos reproduzíveis",
        theory: "Corrigir bugs às cegas gera código desnecessário. A depuração disciplinada segue o método científico: reproduzir o defeito em um script mínimo independente (MRE), formular uma hipótese testável sobre a causa, escrever um teste automatizado que falha demonstrando o erro e aplicar a correção.",
        questions: [
          q("Por que criar um MRE (Minimal Reproducible Example) é o primeiro passo para resolver um bug complexo?", "Porque elimina dependências e ruídos externos, provando exatamente quais condições mínimas disparam o defeito", ["Porque diminui o tamanho do projeto no Git","Porque o cliente exige scripts mínimos por contrato"], "Isolar a falha em 20 linhas de código revela a causa raiz muito antes de tentar mexer na aplicação inteira."),
          q("Qual é o papel de um teste que falha (teste de regressão) antes de qualquer linha de correção ser alterada?", "Comprovar que o bug foi devidamente reproduzido e servir de garantia perpétua contra reaparecimento futuro", ["Garantir que a esteira de CI fique vermelha para sempre","Avisar o suporte que o sistema caiu"], "Se o teste não falha antes do conserto, você não tem como provar se sua edição realmente corrigiu a causa."),
          q("O que caracteriza uma hipótese científica válida durante a depuração de software?", "Uma afirmação falseável e testável: \"a falha ocorre porque a conversão de fuso horário altera o dia em UTC\"", ["Uma suposição vaga: \"o computador não gosta desse código\"","Apostar dinheiro com outro programador"], "Hipóteses testáveis orientam experimentos objetivos com asserções precisas."),
          q("O que a regra de \"uma alteração por vez\" previne durante a tentativa de corrigir um defeito sutil?", "Previne mascarar a causa raiz ou introduzir múltiplos efeitos colaterais novos sem saber qual mudança resolveu", ["Previne o computador de gastar mais bateria","Evita salvar arquivos com nomes longos"], "Alterar uma variável por vez é a essência do isolamento experimental na engenharia."),
          t("Qual sigla em inglês define o exemplo mínimo e autocontido que reproduz um defeito?", ["MRE"], "Minimal Reproducible Example isola o problema de ruídos secundários."),
          g("Complete o ciclo disciplinado escrevendo a asserção que reproduz a falha antes da correção:", ["throws"], "O teste deve demonstrar a falha antes de você modificar o código.", "assert.____(() => processarDadoCorrompido(), /esperado/);"),
          o("Ordene as etapas do método científico para investigação e resolução de defeitos:", ["Reproduzir a falha de forma consistente e documentar as entradas exatas","Construir um exemplo mínimo reproduzível (MRE) isolando o comportamento anômalo","Formular hipóteses testáveis e escrever um teste automatizado que falhe confirmando o bug","Corrigir a causa raiz no código até o teste passar e submeter o commit de regressão"], "Reprodução consistente, isolamento em MRE, teste de falha e correção definitiva."),
          p("Associe a fase de depuração à sua boa prática:", [["MRE","Script isolado sem dependências irrelevantes que recria a falha"],["Hipótese Falseável","Teoria clara sobre a causa raiz passível de prova via asserção"],["Teste de Regressão","Caso de teste automatizado que protege o sistema contra retorno do bug"],["Correção Cirúrgica","Edição mínima estrita focada na causa raiz sem alterar código alheio"]], "Adotar método científico na depuração resolve problemas em minutos que tentativas aleatórias levariam dias.")
        ]
      }
