      {
        id: "javascript-c15-u6-l5-skip-links-e-atalhos-de-navegacao-direta",
        title: "Links de salto (Skip Links) e atalhos de navegação direta",
        subtitle: "Eficiência de fluxo · Permitindo pular dezenas de links de menu e ir direto ao conteúdo",
        theory: "Usuários de teclado podem ter que teclar Tab dezenas de vezes para passar pelo menu antes do texto. Um \"Skip Link\" (<a href=\"#main\" class=\"skip-link\">Pular para o conteúdo</a>) fica oculto até receber foco no primeiro Tab, permitindo saltar direto para a tag principal <main id=\"main\">.",
        questions: [
          q("Qual é o propósito de um \"Skip Link\" (Link de Salto) no topo de um site?", "Permitir que usuários de teclado saltem o cabeçalho e dezenas de links de menu indo direto ao conteúdo principal", ["Aumentar o ranking no Google através de SEO","Baixar arquivos PDF automaticamente"], "Pressionar Tab uma única vez e Enter poupa o usuário de navegar por todo o menu a cada nova página."),
          q("Como o CSS costuma tratar o Skip Link para que ele não polua visualmente quem navega com o mouse?", "O link fica posicionado fora da tela (ex: top: -999px) e torna-se visível no topo quando recebe foco (:focus)", ["O link fica totalmente invisível com display: none para todos","O texto é apagado com JavaScript"], "Usar display: none impediria que ele recebesse foco; mantê-lo fora da tela até :focus preserva o acesso."),
          q("Onde deve apontar o atributo href do Skip Link principal da página?", "Para o identificador da tag principal de conteúdo (ex: href=\"#conteudo-principal\")", ["Para a página inicial do site","Para a política de privacidade"], "O salto ancora a navegação exatamente onde o conteúdo relevante da tela começa."),
          q("Qual atributo deve ser inserido na tag <main id=\"conteudo-principal\"> para garantir que ela receba foco após o salto?", "tabindex=\"-1\", permitindo que o navegador posicione o foco de leitura no contêiner com segurança", ["tabindex=\"1\"","role=\"button\""], "Alguns navegadores só movem o foco de teclado para elementos que possuam tabindex=\"-1\"."),
          t("Qual elemento HTML semântico representa o destino principal de um salto de navegação?", ["main"], "A tag main delimita o conteúdo central e único da página."),
          g("Complete o link de salto acessível ancorando o destino no elemento principal do documento:", ["main"], "Skip links apontam para o identificador do contêiner principal.", "<a href=\"#conteudo\" class=\"skip-link\">Pular para o ____</a>"),
          o("Ordene a estrutura e funcionamento de um Skip Link no topo do HTML:", ["Declarar o link <a href=\"#conteudo\" class=\"skip-link\"> como primeiro elemento do <body>","Estilizar o skip-link no CSS para ficar fora da tela até receber a pseudo-classe :focus","Configurar o contêiner de destino com <main id=\"conteudo\" tabindex=\"-1\">","Validar navegando com o primeiro Tab da página e pressionando Enter para saltar"], "Declaração inicial no body, ocultamento com revelação em :focus, destino no main e teste prático."),
          p("Associe o componente do Skip Link à sua responsabilidade:", [["<a href=\"#conteudo\">","Gatillho de salto posicionado no início absoluto da árvore DOM"],[".skip-link:focus","Regra CSS que torna o link visível e destacado ao receber foco"],["<main id=\"conteudo\">","Região de conteúdo primário para onde o usuário é transportado"],["tabindex=\"-1\" no main","Assegura que o contêiner receba o foco após a âncora de salto"]], "Implementar skip links demonstra respeito profundo pelo tempo e pela ergonomia de quem usa teclado.")
        ]
      }
